cpp.setup:
auto* control = new fluent::windowing::Window(%PARENT%);
control->setWindowTitle(QStringLiteral("Fluent Window"));
auto* titleContent = new QWidget(control->titleBar());
auto* titleLayout = new QHBoxLayout(titleContent);
titleLayout->setContentsMargins(10, 0, 8, 0);
titleLayout->setSpacing(8);
auto* appIcon = new fluent::FontIcon(Typography::Icons::Home, titleContent);
appIcon->setIconSize(14);
titleLayout->addWidget(appIcon);
auto* appName = new fluent::textfields::Label(QStringLiteral("Fluent Window"), titleContent);
appName->setFluentTypography(Typography::FontRole::BodyStrong);
titleLayout->addWidget(appName);
auto* shellTag = new fluent::textfields::Label(QStringLiteral("App shell"), titleContent);
shellTag->setFluentTypography(Typography::FontRole::Caption);
shellTag->setTextColorRole(fluent::textfields::Label::TextColorRole::Secondary);
titleLayout->addWidget(shellTag);
titleLayout->addStretch(1);
control->titleBar()->setContentWidget(titleContent);
auto* body = new QWidget(control);
auto* bodyLayout = new QVBoxLayout(body);
bodyLayout->setContentsMargins(20, 14, 20, 18);
bodyLayout->setSpacing(12);
auto* heading = new fluent::textfields::Label(QStringLiteral("Desktop workspace"), body);
heading->setFluentTypography(Typography::FontRole::Subtitle);
bodyLayout->addWidget(heading);
auto* card = new fluent::layout::Card(body);
card->setAppearance(fluent::layout::Card::LayerAlt);
auto* cardLayout = new QVBoxLayout(card);
cardLayout->setContentsMargins(16, 12, 16, 14);
cardLayout->setSpacing(8);
auto* cardTitle = new fluent::textfields::Label(QStringLiteral("Backdrop & window chrome"), card);
cardTitle->setFluentTypography(Typography::FontRole::BodyStrong);
cardLayout->addWidget(cardTitle);
auto* cardDesc = new fluent::textfields::Label(QStringLiteral("Switch Backdrop effect below to compare Solid, Mica, and Acrylic surfaces."), card);
cardDesc->setFluentTypography(Typography::FontRole::Caption);
cardDesc->setTextColorRole(fluent::textfields::Label::TextColorRole::Secondary);
cardDesc->setWordWrap(true);
cardLayout->addWidget(cardDesc);
auto* actions = new QHBoxLayout;
actions->setSpacing(8);
auto* primary = new fluent::basicinput::Button(QStringLiteral("New project"), card);
primary->setFluentStyle(fluent::basicinput::Button::Accent);
primary->setFluentSize(fluent::basicinput::Button::Small);
auto* secondary = new fluent::basicinput::Button(QStringLiteral("Settings"), card);
secondary->setFluentSize(fluent::basicinput::Button::Small);
actions->addWidget(primary);
actions->addWidget(secondary);
actions->addStretch(1);
cardLayout->addLayout(actions);
bodyLayout->addWidget(card);
bodyLayout->addStretch(1);
control->setContentWidget(body);
